    limit::Union{Int, Nothing} = nothing
    mentions::Union{String, Nothing} = nothing
    since::Union{String, Nothing} = nothing
    sort::Union{String, Nothing} = nothing
    tag::Union{Vector{String}, Nothing} = nothing
    until::Union{String, Nothing} = nothing
    url::Union{String, Nothing} = nothing
    viewer::Union{DID, Nothing} = nothing
end

