    includeAllUserRecords::Union{Bool, Nothing} = nothing
    includeMuted::Union{Bool, Nothing} = nothing
    lastReviewedBy::Union{DID, Nothing} = nothing
    limit::Union{Int, Nothing} = nothing
    minAccountSuspendCount::Union{Int, Nothing} = nothing
